// Input: items[] where each item.json = { path, code }
// Output: multiple chunk items per file

const maxLen = 1200;

// semantic Dart separators
const separators = [
  /\nclass /,
  /\nimport /,
  /\nvoid /,
  /\nFuture</,
  /\nWidget /,
  /\n@override/,
  /\nenum /,
  /\nextends /,
  /\nabstract /,
];

function chunkDartCode(code) {
  const lines = code.split("\n");
  const chunks = [];
  let current = "";

  for (const line of lines) {
    // split on semantic code boundaries
    if (separators.some(re => re.test("\n" + line))) {
      if (current.trim().length > 0) {
        chunks.push(current.trim());
        current = "";
      }
    }

    // normal length-based cutoff
    if ((current + "\n" + line).length > maxLen) {
      if (current.trim().length > 0) {
        chunks.push(current.trim());
      }
      current = line;
    } else {
      current += "\n" + line;
    }
  }

  if (current.trim().length > 0) chunks.push(current.trim());
  return chunks;
}

let out = [];

for (const item of items) {
  const file = item.json.path;
  const code = item.json.code || "";

  const codeChunks = chunkDartCode(code);

  codeChunks.forEach((chunk, index) => {
    out.push({
      json: {
        file,
        chunkIndex: index,
        content: chunk,
      },
    });
  });
}

return out;

