// Use Sets to track unique files (avoid duplicates if file modified twice in one push)
const filesToIngest = new Set();
const filesToDelete = new Set();

for (const commit of commits) {
  // 1. Files that need new vectors (Added + Modified)
  commit.added.forEach(path => filesToIngest.add(path));
  commit.modified.forEach(path => filesToIngest.add(path));

  // 2. Files that need old vectors removed (Removed + Modified)
  commit.removed.forEach(path => filesToDelete.add(path));
  commit.modified.forEach(path => filesToDelete.add(path));
}

